import os
from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final[Path] = Path("notes")


def resolve_note(name: str) -> Path | None:
    """Return the path of the note called name inside NOTES_DIR, or None if unsafe.

    Rejects empty names, names containing NUL bytes, absolute paths, names that
    traverse out of NOTES_DIR (for example "../x" or "a/../../x"), and names whose
    fully resolved location (following symlinks) lies outside NOTES_DIR.
    Does not require the file to exist.
    """
    if not name or "\x00" in name:
        return None
    raw = Path(name)
    if raw.is_absolute() or raw.drive or raw.root:
        return None
    try:
        base = NOTES_DIR.resolve()
        candidate = (base / raw).resolve()
    except (OSError, RuntimeError, ValueError):
        return None
    if candidate == base or not candidate.is_relative_to(base):
        return None
    return candidate


def try_read_note(name: str) -> str | None:
    """Return the contents of the readable note called name, or None.

    Returns None when the name is unsafe per resolve_note, the file is missing,
    the path is not a regular file, or it cannot be read.
    """
    path = resolve_note(name)
    if path is None:
        return None
    try:
        if not path.is_file():
            return None
        return path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


def read_note(name: str) -> str:
    """Return the contents of the note called name, or "" when try_read_note gives None."""
    content = try_read_note(name)
    return "" if content is None else content


def count_readable(names: list[str]) -> int:
    """Count how many names are readable note files inside NOTES_DIR.

    Each name is checked with try_read_note; names that yield None are not counted.
    Unsafe, missing, or unreadable names never raise and never read outside NOTES_DIR.
    """
    return sum(1 for name in names if try_read_note(name) is not None)


@pytest.fixture
def notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Work in tmp_path with a notes/ directory containing a.txt and empty.txt.

    A secret.txt sits beside notes/, outside it, to catch escapes.
    """
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (notes / "empty.txt").write_text("", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("top secret", encoding="utf-8")
    return notes


def test_count_empty_list_is_zero(notes_dir: Path) -> None:
    assert count_readable([]) == 0


def test_count_includes_readable_files_even_if_empty(notes_dir: Path) -> None:
    assert count_readable(["a.txt", "empty.txt"]) == 2


def test_count_skips_missing_names(notes_dir: Path) -> None:
    assert count_readable(["a.txt", "nope.txt"]) == 1


def test_traversal_names_not_counted_and_not_read(notes_dir: Path) -> None:
    names = ["../secret.txt", "sub/../../secret.txt", "a.txt/../../secret.txt"]
    assert count_readable(names) == 0
    for name in names:
        assert read_note(name) == ""


def test_absolute_path_outside_notes_not_counted(notes_dir: Path, tmp_path: Path) -> None:
    assert count_readable([str(tmp_path / "secret.txt")]) == 0
    assert read_note(str(tmp_path / "secret.txt")) == ""


def test_directory_not_counted(notes_dir: Path) -> None:
    (notes_dir / "sub").mkdir()
    assert count_readable(["sub"]) == 0
    assert read_note("sub") == ""


def test_symlink_escaping_notes_not_counted(notes_dir: Path, tmp_path: Path) -> None:
    link = notes_dir / "link.txt"
    try:
        os.symlink(tmp_path / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported here")
    assert count_readable(["link.txt"]) == 0
    assert read_note("link.txt") == ""


def test_nul_byte_name_not_counted_and_no_error(notes_dir: Path) -> None:
    assert count_readable(["a.txt\x00", "\x00"]) == 0


def test_mixed_batch_counts_only_good_names(notes_dir: Path) -> None:
    names = ["a.txt", "../secret.txt", "missing.txt", "empty.txt", "/etc/passwd"]
    assert count_readable(names) == 2


@pytest.mark.parametrize(
    "name",
    ["", "../secret.txt", "a/../../secret.txt", "/etc/passwd", "bad\x00name"],
)
def test_resolve_note_rejects_unsafe_names(notes_dir: Path, name: str) -> None:
    assert resolve_note(name) is None


def test_resolve_note_accepts_plain_name(notes_dir: Path) -> None:
    result = resolve_note("a.txt")
    assert result is not None
    assert result.name == "a.txt"


def test_read_note_returns_contents(notes_dir: Path) -> None:
    assert read_note("a.txt") == "hello"


def test_read_note_missing_is_empty_string(notes_dir: Path) -> None:
    assert read_note("missing.txt") == ""


def test_try_read_note_distinguishes_missing_from_empty(notes_dir: Path) -> None:
    assert try_read_note("empty.txt") == ""
    assert try_read_note("missing.txt") is None
